CREATE TYPE "WebsiteDeploymentStatus" AS ENUM ('DRAFT', 'QUEUED', 'BUILDING', 'READY', 'PUBLISHING', 'PUBLISHED', 'FAILED', 'ROLLED_BACK');
CREATE TYPE "WebsiteDomainStatus" AS ENUM ('PENDING_VERIFICATION', 'VERIFIED', 'PROVISIONING', 'ACTIVE', 'FAILED', 'DISCONNECTED');
CREATE TYPE "HostingSubscriptionStatus" AS ENUM ('PENDING_PAYMENT', 'ACTIVE', 'PAST_DUE', 'CANCELLED', 'EXPIRED');

CREATE TABLE "HostedWebsite" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "userId" UUID NOT NULL, "projectId" UUID NOT NULL, "name" TEXT NOT NULL, "slug" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'DRAFT', "activeDeploymentId" UUID, "deletedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "HostedWebsite_pkey" PRIMARY KEY ("id"));
CREATE TABLE "WebsiteDeployment" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "websiteId" UUID NOT NULL, "revisionId" UUID NOT NULL, "number" INTEGER NOT NULL, "status" "WebsiteDeploymentStatus" NOT NULL DEFAULT 'DRAFT', "snapshot" JSONB NOT NULL, "idempotencyKey" TEXT NOT NULL, "errorCode" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "publishedAt" TIMESTAMP(3), CONSTRAINT "WebsiteDeployment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "WebsiteDomain" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "websiteId" UUID NOT NULL, "hostname" TEXT NOT NULL, "status" "WebsiteDomainStatus" NOT NULL DEFAULT 'PENDING_VERIFICATION', "verificationToken" TEXT, "verifiedAt" TIMESTAMP(3), "isPrimary" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "WebsiteDomain_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DomainVerification" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "domainId" UUID NOT NULL, "method" TEXT NOT NULL, "tokenHash" TEXT NOT NULL, "checkedAt" TIMESTAMP(3), "attempts" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "DomainVerification_pkey" PRIMARY KEY ("id"));
CREATE TABLE "WebsiteHostingPlan" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "code" TEXT NOT NULL, "name" TEXT NOT NULL, "priceMmk" INTEGER NOT NULL, "websitesLimit" INTEGER NOT NULL, "customDomainsLimit" INTEGER NOT NULL, "storageLimitMb" INTEGER NOT NULL, "bandwidthLimitMb" INTEGER NOT NULL, "monthlyVisitsLimit" INTEGER NOT NULL, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "WebsiteHostingPlan_pkey" PRIMARY KEY ("id"));
CREATE TABLE "HostingSubscription" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "userId" UUID NOT NULL, "websiteId" UUID NOT NULL, "planId" UUID NOT NULL, "status" "HostingSubscriptionStatus" NOT NULL DEFAULT 'PENDING_PAYMENT', "currency" TEXT NOT NULL DEFAULT 'MMK', "priceMmk" INTEGER NOT NULL, "startsAt" TIMESTAMP(3), "renewsAt" TIMESTAMP(3), "cancelledAt" TIMESTAMP(3), "idempotencyKey" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "HostingSubscription_pkey" PRIMARY KEY ("id"));
CREATE TABLE "HostingInvoice" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "invoiceNumber" TEXT NOT NULL, "userId" UUID NOT NULL, "planId" UUID NOT NULL, "subscriptionId" UUID, "amountMmk" INTEGER NOT NULL, "currency" TEXT NOT NULL DEFAULT 'MMK', "snapshot" JSONB NOT NULL, "status" TEXT NOT NULL DEFAULT 'ISSUED', "dueAt" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "HostingInvoice_pkey" PRIMARY KEY ("id"));
CREATE TABLE "HostingPayment" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "invoiceId" UUID NOT NULL, "userId" UUID NOT NULL, "amountMmk" INTEGER NOT NULL, "currency" TEXT NOT NULL DEFAULT 'MMK', "status" TEXT NOT NULL DEFAULT 'PENDING', "transactionReference" TEXT, "proofStorageKey" TEXT, "idempotencyKey" TEXT NOT NULL, "reviewedAt" TIMESTAMP(3), "reviewerId" UUID, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "HostingPayment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "HostingUsageRecord" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "websiteId" UUID NOT NULL, "periodStart" TIMESTAMP(3) NOT NULL, "periodEnd" TIMESTAMP(3) NOT NULL, "websites" INTEGER NOT NULL DEFAULT 1, "storageMb" INTEGER NOT NULL DEFAULT 0, "bandwidthMb" INTEGER NOT NULL DEFAULT 0, "visits" INTEGER NOT NULL DEFAULT 0, "isEstimated" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "HostingUsageRecord_pkey" PRIMARY KEY ("id"));
CREATE TABLE "WebsiteAnalyticsEvent" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "websiteId" UUID NOT NULL, "eventName" TEXT NOT NULL, "path" TEXT NOT NULL, "source" TEXT, "device" TEXT, "dedupeKey" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "WebsiteAnalyticsEvent_pkey" PRIMARY KEY ("id"));
CREATE TABLE "WebsiteDeploymentLog" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "deploymentId" UUID NOT NULL, "level" TEXT NOT NULL, "message" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "WebsiteDeploymentLog_pkey" PRIMARY KEY ("id"));
CREATE TABLE "WebsiteHostingAuditLog" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "websiteId" UUID, "userId" UUID NOT NULL, "action" TEXT NOT NULL, "metadata" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "WebsiteHostingAuditLog_pkey" PRIMARY KEY ("id"));

